import React, { useState } from 'react'
import '../app.css'
import Countrycard from "./countrycard";
import countryData from "../countryData.js";

export default function CountryList({query}) {
  // Bundled dataset (no network dependency); independent countries only,
  // matching the previous API behavior.
  const [countries] = useState(() => countryData.filter((c) => c.independent));
  const q = (query || '').toLowerCase();

  const filtered = countries.filter((country) =>
    country.name.common.toLowerCase().includes(q) ||
    (country.region || '').toLowerCase().includes(q)
  );

  return (
    <div className="country-cards">
        {filtered.map((country)=>{
           return <Countrycard
           key={country.cca3}
           name={country.name.common}
           flag={country.flags.svg}
           population={country.population}
           region={country.region}
           capital={country.capital?.[0]}
           data={country}
           />
        })}

    </div>
  )
}
